class Solution {
    public long sumOfCompatibleNumbers(long left, long right, long d) {
        long first = ((left + d - 1) / d) * d;
        long last = (right / d) * d;
        if (first > last) return 0;
        long count = (last - first) / d + 1;
        return count * (first + last) / 2;
    }
}

function sumOfCompatibleNumbers(left, right, d) {
    const l = BigInt(left);
    const r = BigInt(right);
    const divisor = BigInt(d);
    const first = ((l + divisor - 1n) / divisor) * divisor;
    const last = (r / divisor) * divisor;
    if (first > last) return 0;
    const count = (last - first) / divisor + 1n;
    return Number(count * (first + last) / 2n);
}
